export type Recipient = {
  id: string
  name: string
  maskedAccount: string
  currency: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", maskedAccount: "•••• 4821", currency: "NGN" },
  { id: "r2", name: "Lucas Meier", maskedAccount: "•••• 0093", currency: "EUR" },
  { id: "r3", name: "Priya Nair", maskedAccount: "•••• 5570", currency: "INR" },
  { id: "r4", name: "Tom Fletcher", maskedAccount: "•••• 2214", currency: "GBP" },
]

export type SendMoneyData = {
  recipient: Recipient | null
  sendAmount: string
  sendCurrency: string
  receiveCurrency: string
  confirmed: boolean
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipient: null,
  sendAmount: "",
  sendCurrency: "USD",
  receiveCurrency: "EUR",
  confirmed: false,
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (p: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}

/** Mock FX: fixed rate + flat fee, used by Amount and Review. */
export const FX_RATE = 0.91
export const FLAT_FEE = 4.99

export function recipientGets(sendAmount: string): number {
  const n = Number.parseFloat(sendAmount)
  if (!Number.isFinite(n) || n <= 0) return 0
  return n * FX_RATE
}

export function totalToPay(sendAmount: string): number {
  const n = Number.parseFloat(sendAmount)
  if (!Number.isFinite(n) || n <= 0) return 0
  return n + FLAT_FEE
}

