"use client"

import { useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = RECENT_RECIPIENTS.filter((r) =>
    r.name.toLowerCase().includes(query.trim().toLowerCase())
  )

  const select = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id) ?? null
    patch({ recipient })
    next()
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          type="search"
          placeholder="Name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)", fontWeight: "var(--atlas-font-weight-medium)" }}>
          Recent recipients
        </span>
        {filtered.length === 0 && (
          <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
            No recipients match &ldquo;{query}&rdquo;.
          </span>
        )}
        {filtered.map((recipient) => (
          <RecipientRow
            key={recipient.id}
            recipient={recipient}
            selected={data.recipient?.id === recipient.id}
            onSelect={() => select(recipient.id)}
          />
        ))}
      </div>
    </div>
  )
}

