"use client"

import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { FLAT_FEE, FX_RATE, recipientGets, totalToPay } from "../schema"
import type { SendMoneyStepProps } from "../schema"

function isValidAmount(value: string): boolean {
  const n = Number.parseFloat(value)
  return Number.isFinite(n) && n > 0
}

export function Amount({ data, patch, next }: SendMoneyStepProps) {
  const valid = isValidAmount(data.sendAmount)
  const gets = recipientGets(data.sendAmount)
  const total = totalToPay(data.sendAmount)

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div>
        <Label htmlFor="send-amount" size="sm" required>
          You send
        </Label>
        <Input
          id="send-amount"
          inputMode="decimal"
          placeholder="0.00"
          suffix={data.sendCurrency}
          value={data.sendAmount}
          onChange={(e) => patch({ sendAmount: e.target.value })}
        />
      </div>

      <div>
        <Label htmlFor="recipient-gets" size="sm">
          Recipient gets
        </Label>
        <Input
          id="recipient-gets"
          readOnly
          suffix={data.receiveCurrency}
          value={gets > 0 ? gets.toFixed(2) : ""}
        />
      </div>

      <Card variant="outlined" size="sm">
        <CardContent>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
            <Row label="Fee" value={`${data.sendCurrency} ${FLAT_FEE.toFixed(2)}`} />
            <Row label="Exchange rate" value={`1 ${data.sendCurrency} = ${FX_RATE} ${data.receiveCurrency}`} />
            <Row label="Total to pay" value={`${data.sendCurrency} ${total > 0 ? total.toFixed(2) : "0.00"}`} strong />
          </div>
        </CardContent>
      </Card>

      <Alert variant="info" title="Arrives in 1–2 business days" description="Most transfers to this recipient arrive within two days." />

      <Button variant="primary" size="lg" disabled={!valid} onClick={next}>
        Continue
      </Button>
    </div>
  )
}

function Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>{label}</span>
      <span
        style={{
          fontSize: "var(--atlas-text-body-sm)",
          color: "var(--atlas-foreground)",
          fontWeight: strong ? "var(--atlas-font-weight-semibold)" : "var(--atlas-font-weight-regular)",
        }}
      >
        {value}
      </span>
    </div>
  )
}

